package com.insight.quantlife.tests;
import android.app.*;import android.os.*;import org.json.*;import java.io.*;import java.net.*;import java.lang.reflect.*;
/** Production Android WebView/SQLite; synthetic failures are isolated from paid live QA. */
public final class LayoutRecoveryTest extends DocumentEditorTest {
 String source;
 String fixture(String name)throws Exception{try(InputStream in=getContext().getAssets().open(name);ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1)out.write(b,0,n);return out.toString("UTF-8").trim();}}
 void startCase(String body,String mode)throws Exception{open("learning");input("数据化决策",body);h.js("__layoutMode="+JSONObject.quote(mode)+";__layoutAttempts=0;document.querySelector('#doc-more').click()");click("#doc-format");until("!document.querySelector('#doc-format').disabled");}
 boolean visibleError()throws Exception{return h.js("(()=>{const b=document.querySelector('#doc-status'),r=b.getBoundingClientRect();return !b.hidden&&b.getAttribute('role')==='alert'&&b.contains(document.elementFromPoint(r.left+8,r.top+8))&&!!document.querySelector('#doc-format-retry')})()").equals("true");}
 void nativeResponse(String finish,String content,boolean success)throws Exception{
  final ServerSocket server=new ServerSocket(0);final JSONObject[] captured={null};final Throwable[] failure={null};
  Thread thread=new Thread(()->{try(Socket socket=server.accept()){socket.setSoTimeout(10000);InputStream in=socket.getInputStream();ByteArrayOutputStream header=new ByteArrayOutputStream();int x;while((x=in.read())!=-1){header.write(x);if(header.toString("UTF-8").endsWith("\r\n\r\n"))break;}String headers=header.toString("UTF-8");java.util.regex.Matcher m=java.util.regex.Pattern.compile("(?im)^Content-Length: *([0-9]+)").matcher(headers);if(!m.find())throw new Exception("Missing length");int length=Integer.parseInt(m.group(1));byte[] bytes=new byte[length];for(int at=0;at<length;){int n=in.read(bytes,at,length-at);if(n<0)throw new Exception("Incomplete body");at+=n;}captured[0]=new JSONObject(new String(bytes,"UTF-8"));JSONObject message=new JSONObject().put("content",content==null?JSONObject.NULL:content);if(success)message.put("tool_calls",new JSONArray().put(new JSONObject().put("function",new JSONObject().put("name","plan_record_layout").put("arguments","{\"sections\":[]}"))));byte[] data=new JSONObject().put("choices",new JSONArray().put(new JSONObject().put("finish_reason",finish).put("message",message))).toString().getBytes("UTF-8");OutputStream out=socket.getOutputStream();out.write(("HTTP/1.1 200 OK\r\nContent-Type: application/json\r\nContent-Length: "+data.length+"\r\nConnection: close\r\n\r\n").getBytes("UTF-8"));out.write(data);out.flush();}catch(Throwable e){failure[0]=e;}});thread.start();
  h.call("saveSettings",new JSONObject().put("settings",new JSONObject().put("profile",new JSONObject().put("id","custom").put("label","Local native QA").put("baseUrl","http://127.0.0.1:"+server.getLocalPort()+"/v1").put("model","synthetic").put("protocol","chat").put("effort","off").put("apiKey","synthetic-local"))));
  try{Object answer=h.call("ask",new JSONObject(h.js("DocumentLayout.request(DocumentLayout.units('测试正文。'),'标题',0,1)")));check(success,"Only complete native tool responses succeed");check(((JSONObject)answer).getString("text").contains("sections"),"Native complete tool arguments reach JS");}catch(InvocationTargetException e){if(success)throw e;String message=String.valueOf(e.getCause().getMessage());check(message.contains(finish.equals("length")?"输出达到上限":"模型未返回文本"),"Native empty/truncated response has explicit retryable error: "+finish);}finally{thread.join(10000);server.close();}
  if(failure[0]!=null)throw new Exception(failure[0]);check(captured[0]!=null&&captured[0].getInt("max_tokens")==8192,"Layout output budget is 8192");check(captured[0].getJSONObject("tool_choice").getJSONObject("function").getString("name").equals("plan_record_layout"),"Non-reasoning layout forces correct structured tool");
 }
 @Override public void onStart(){Bundle out=new Bundle();try{
  h=new MainHost(this);h.open();model();source=fixture("layout-decision.txt");
  h.js("window.__layoutOriginal=LifeNative;window.__layoutMode='good';window.__layoutAttempts=0;window.__layoutPlan=us=>({sections:[{heading:['万事均可量化'],blocks:[{ids:us.slice(0,3).map(u=>u.id),style:'paragraph',emphasis:[]},{ids:us.slice(3,7).map(u=>u.id),style:'paragraph',emphasis:[]}]},{heading:['数据决策的步骤'],blocks:[{ids:us.slice(7).map(u=>u.id),style:'paragraph',emphasis:[]}]}]});LifeNative={call:(a,p,id)=>{const req=JSON.parse(p);if(a!=='ask'||req.tool?.name!=='plan_record_layout'){__layoutOriginal.call(a,p,id);return;}__layoutAttempts++;const us=JSON.parse(req.messages[1].content).units;let result;if(__layoutMode==='network'||__layoutMode==='auth')result={id,error:__layoutMode==='auth'?'模型服务拒绝认证（401）':'无法连接模型服务，请检查网络和 API 地址'};else if(__layoutMode==='empty'&&__layoutAttempts===1)result={id,error:'模型未返回文本，请稍后重试'};else{let plan=__layoutMode==='invalid'||__layoutMode==='recover'&&__layoutAttempts===1?{sections:[]}:__layoutMode==='noop'?{sections:[{heading:[],blocks:[{ids:us.map(u=>u.id),style:'paragraph',emphasis:[]}]}]}:__layoutPlan(us);result={id,data:{text:JSON.stringify(plan),model:'synthetic-layout-qa'}};}setTimeout(()=>nativeReply(result),60);}};");
  for(String mode:new String[]{"good","recover","empty"}){startCase(source,mode);check(h.js("!!document.querySelector('#doc-preview')").equals("true"),"Complete preview after "+mode);check(h.js("__layoutAttempts").equals(mode.equals("good")?"1":"2"),"Bounded attempt count for "+mode);check(h.js("document.querySelectorAll('#doc-flow ol>li').length===5").equals("true"),"Five complete steps, not comma-sized items: "+mode);check(h.js("DocumentRich.serialize(document.querySelector('#doc-body'))").equals(JSONObject.quote(source)),"Original retained before adoption: "+mode);if(mode.equals("good")){h.screenshot("layout-fixed-preview.png");click("#doc-apply");check(!h.js("DocumentRich.serialize(document.querySelector('#doc-body'))").equals(JSONObject.quote(source)),"Adopted structure updates note");click("#doc-undo");check(h.js("DocumentRich.serialize(document.querySelector('#doc-body'))").equals(JSONObject.quote(source)),"Undo restores exact source");}close();}
  String marked=source.replace("万事均可量化","**万事均可量化**");startCase(marked,"good");check(h.js("!!document.querySelector('#doc-preview')&&document.querySelectorAll('#doc-flow ol>li').length===5&&document.querySelector('#doc-flow strong').textContent==='万事均可量化'").equals("true"),"Existing inline emphasis no longer prevents restructuring");h.screenshot("layout-fixed-bold-preview.png");close();
  for(String mode:new String[]{"invalid","network","auth"}){startCase(source,mode);check(visibleError(),"Failure is visible inside modal with retry button: "+mode);check(h.js("__layoutAttempts").equals(mode.equals("invalid")?"2":"1"),"No infinite retry for "+mode);check(h.js("!document.querySelector('#doc-preview')&&DocumentRich.serialize(document.querySelector('#doc-body'))").equals(JSONObject.quote(source)),"Failure never replaces original: "+mode);if(mode.equals("invalid")){h.screenshot("layout-fixed-error.png");h.js("__layoutMode='good'");click("#doc-format-retry");until("!!document.querySelector('#doc-preview')");check(h.js("document.querySelector('#doc-status').hidden").equals("true"),"Manual retry recovers and clears persistent error");}close();}
  startCase("只有一段，保持原样。","noop");check(visibleError()&&h.js("document.querySelector('#doc-status').textContent.includes('未生成新的排版')").equals("true"),"Unchanged output is reported, not passed off as success");close();
  Class<?> endpoint=Class.forName("com.insight.quantlife.ModelEndpoint");Method bailian=endpoint.getDeclaredMethod("bailian",URL.class);bailian.setAccessible(true);for(String host:new String[]{"dashscope.aliyuncs.com","dashscope-intl.aliyuncs.com","llm-workspace.cn-beijing.maas.aliyuncs.com"})check((Boolean)bailian.invoke(null,new URL("https://"+host+"/v1/chat/completions")),"Bailian host recognized: "+host);for(String host:new String[]{"api.deepseek.com","dashscope.aliyuncs.com.attacker.test","my-maas.aliyuncs.com"})check(!(Boolean)bailian.invoke(null,new URL("https://"+host+"/v1/chat/completions")),"No Bailian parameters for other provider: "+host);
  nativeResponse("stop",null,false);nativeResponse("length","partial",false);nativeResponse("tool_calls",null,true);
  out.putString("stream","PASS LayoutRecoveryTest: "+passed+" checks; synthetic replies/local HTTP only\n");finish(Activity.RESULT_OK,out);
 }catch(Throwable e){try{h.screenshot("layout-recovery-failure.png");}catch(Exception ignored){}out.putString("stream","FAIL LayoutRecoveryTest after "+passed+": "+e+"\n");finish(Activity.RESULT_CANCELED,out);}}
}
